import itertools

def solve_small(n):
    squares = [(r, c) for r in range(n) for c in range(n)]
    adj = {s: [] for s in squares}
    for r1, c1 in squares:
        for r2, c2 in squares:
            if (r1, c1) != (r2, c2) and max(abs(r1 - r2), abs(c1 - c2)) == 1:
                adj[(r1, c1)].append((r2, c2))

    max_k = 0
    # This is small, so we can use some backtracking or a more clever approach.
    # For N=3, 9 squares, 2^9 = 512 combinations.
    for i in range(1 << (n*n)):
        subset = []
        for j in range(n*n):
            if (i >> j) & 1:
                subset.append(squares[j])

        valid = True
        for s in subset:
            count = 0
            for neighbor in adj[s]:
                if neighbor in subset:
                    count += 1
            if count > 1:
                valid = False
                break
        if valid:
            max_k = max(max_k, len(subset))
    return max_k

