import itertools

def solve_small(n):
    # King's graph adjacency
    adj = {}
    for r in range(n):
        for c in range(n):
            neighbors = []
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < n:
                        neighbors.append((nr, nc))
            adj[(r, c)] = neighbors

    # We want to find the max size of a subset S such that the induced subgraph
    # has max degree 1.
    # Since n is small, we can use backtracking or a bitmask.
    # For n=3, there are 2^9 = 512 subsets.
    max_k = 0
    for i in range(1 << (n*n)):
        subset = []
        for bit in range(n*n):
            if (i >> bit) & 1:
                subset.append((bit // n, bit % n))

        # Check if induced subgraph has max degree 1
        is_valid = True
        for u in subset:
            neighbors_in_subset = 0
            for v in subset:
                if u != v and v in adj[u]:
                    neighbors_in_subset += 1
            if neighbors_in_subset > 1:
                is_valid = False
                break

        if is_valid:
            max_k = max(max_k, len(subset))
    return max_k

