def solve_n(n):
    adj = []
    for r in range(n):
        for c in range(n):
            neighbors = 0
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0: continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < n:
                        neighbors |= (1 << (nr * n + nc))
            adj.append(neighbors)

    max_k = 0

    # Use a recursive search with pruning
    def find_max(idx, current_mask, current_k):
        nonlocal max_k
        if idx == n * n:
            max_k = max(max_k, current_k)
            return

        if current_k + (n * n - idx) <= max_k:
            return

        # Option 1: Skip idx
        find_max(idx + 1, current_mask, current_k)

        # Option 2: Include idx
        neighbors_in_mask = adj[idx] & current_mask
        num_neighbors = bin(neighbors_in_mask).count('1')

        if num_neighbors <= 1:
            can_add = True
            if num_neighbors == 1:
                # Find the neighbor
                neighbor_idx = (neighbors_in_mask).bit_length() - 1
                # The neighbor already has 0 neighbors in current_mask
                # but it will have 1 neighbor (idx) in the new mask.
                # So it's okay as long as it had 0 before.
                if bin(adj[neighbor_idx] & current_mask).count('1') > 0:
                    can_add = False

            if can_add:
                find_max(idx + 1, current_mask | (1 << idx), current_k + 1)

    find_max(0, 0, 0)
    return max_k

