# Let's try a simple backtracking with some pruning
def solve_small(n):
    grid = [[False] * n for _ in range(n)]
    max_k = 0

    def get_neighbors(r, c):
        res = []
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < n:
                    res.append((nr, nc))
        return res

    def backtrack(r, c, current_k):
        nonlocal max_k
        if r == n:
            max_k = max(max_k, current_k)
            return

        next_r, next_c = (r, c + 1) if c + 1 < n else (r + 1, 0)

        # Option 1: Don't pick (r, c)
        backtrack(next_r, next_c, current_k)

        # Option 2: Pick (r, c)
        # Check if picking (r, c) is valid
        # (r, c) must have at most one neighbor in the set of already picked squares
        # AND every already picked square that is a neighbor of (r, c) must have 0 other neighbors

        picked_neighbors = []
        for nr, nc in get_neighbors(r, c):
            if nr < r or (nr == r and nc < c):
                if grid[nr][nc]:
                    picked_neighbors.append((nr, nc))

        if len(picked_neighbors) <= 1:
            # Also check if any of these neighbors already has a neighbor
            can_pick = True
            for nr, nc in picked_neighbors:
                # How many neighbors does (nr, nc) have?
                count = 0
                for nnr, nnc in get_neighbors(nr, nc):
                    if nnr < r or (nnr == r and nnc < c):
                        if grid[nnr][nnc]:
                            count += 1
                if count >= 1:
                    can_pick = False
                    break

            if can_pick:
                grid[r][c] = True
                backtrack(next_r, next_c, current_k + 1)
                grid[r][c] = False

    backtrack(0, 0, 0)
    return max_k

