def solve_n_optimized(n):
    squares = [(r, c) for r in range(n) for c in range(n)]
    adj = {s: [] for s in squares}
    for r1, c1 in squares:
        for r2, c2 in squares:
            if (r1, c1) != (r2, c2) and max(abs(r1 - r2), abs(c1 - c2)) == 1:
                adj[(r1, c1)].append((r2, c2))

    best_k = 0

    def backtrack(idx, current_subset, current_degrees):
        nonlocal best_k
        if idx == len(squares):
            best_k = max(best_k, len(current_subset))
            return

        if len(current_subset) + (len(squares) - idx) <= best_k:
            return

        s = squares[idx]

        # Option 1: Don't include s
        backtrack(idx + 1, current_subset, current_degrees)

        # Option 2: Include s
        neighbors_in_subset = [nb for nb in adj[s] if nb in current_subset]

        if len(neighbors_in_subset) == 0:
            current_subset.add(s)
            current_degrees[s] = 0
            backtrack(idx + 1, current_subset, current_degrees)
            current_subset.remove(s)
            del current_degrees[s]
        elif len(neighbors_in_subset) == 1:
            nb = neighbors_in_subset[0]
            if current_degrees[nb] == 0:
                current_subset.add(s)
                current_degrees[s] = 1
                current_degrees[nb] = 1
                backtrack(idx + 1, current_subset, current_degrees)
                current_degrees[nb] = 0
                current_subset.remove(s)
                del current_degrees[s]

    backtrack(0, set(), {})
    return best_k

