def solve_small(n):
    grid = [(i, j) for i in range(n) for j in range(n)]
    adj = {s: [] for s in grid}
    for i, j in grid:
        for di in [-1, 0, 1]:
            for dj in [-1, 0, 1]:
                if di == 0 and dj == 0:
                    continue
                ni, nj = i + di, j + dj
                if 0 <= ni < n and 0 <= nj < n:
                    adj[(i, j)].append((ni, nj))

    max_k = 0
    # This is a maximum independent set problem if we were looking for delta=0.
    # For delta=1, it's more complex.
    # We can use backtracking with pruning.

    def is_valid(current_set):
        for s in current_set:
            neighbors_in_set = [neigh for neigh in adj[s] if neigh in current_set]
            if len(neighbors_in_set) > 1:
                return False
        return True

    # For small n, we can just iterate through all subsets.
    # But n=4 already has 2^16 = 65536 subsets.
    # Let's use a more efficient approach.

    def backtrack(index, current_set):
        nonlocal max_k
        if index == len(grid):
            if len(current_set) > max_k:
                max_k = len(current_set)
            return

        # Pruning
        if len(current_set) + (len(grid) - index) <= max_k:
            return

        # Try including grid[index]
        s = grid[index]
        neighbors_in_set = [neigh for neigh in adj[s] if neigh in current_set]

        # Check if s can be added:
        # 1. s must have at most 1 neighbor in current_set.
        # 2. Any neighbor of s already in current_set must have at most 0 neighbors in current_set (besides s).

        can_add = True
        if len(neighbors_in_set) > 1:
            can_add = False
        else:
            for neigh in neighbors_in_set:
                # neigh is already in current_set.
                # How many neighbors does neigh have in current_set?
                neigh_neighbors_in_set = [n_neigh for n_neigh in adj[neigh] if n_neigh in current_set]
                if len(neigh_neighbors_in_set) >= 1: # It already has s (well, s is not in current_set yet)
                    # Wait, current_set doesn't have s yet.
                    # So neigh_neighbors_in_set is the set of neighbors of neigh in current_set.
                    # If neigh already has a neighbor in current_set, then adding s would give it two.
                    if len(neigh_neighbors_in_set) >= 1:
                        can_add = False
                        break

        if can_add:
            backtrack(index + 1, current_set | {s})

        # Try not including grid[index]
        backtrack(index + 1, current_set)

