def solve_n(n):
    grid = [(i, j) for i in range(n) for j in range(n)]
    adj = {s: [] for s in grid}
    for i, j in grid:
        for di in [-1, 0, 1]:
            for dj in [-1, 0, 1]:
                if di == 0 and dj == 0: continue
                ni, nj = i + di, j + dj
                if 0 <= ni < n and 0 <= nj < n:
                    adj[(i, j)].append((ni, nj))

    # We want to find a maximum set S such that each s in S has at most 1 neighbor in S.
    # This is equivalent to picking a set of disjoint edges and isolated vertices
    # such that no two of them are adjacent.

    max_k = 0
    def backtrack(index, current_set):
        nonlocal max_k
        if index == len(grid):
            max_k = max(max_k, len(current_set))
            return

        if len(current_set) + (len(grid) - index) <= max_k:
            return

        s = grid[index]
        neighbors_in_set = [neigh for neigh in adj[s] if neigh in current_set]

        can_add = True
        if len(neighbors_in_set) > 1:
            can_add = False
        else:
            for neigh in neighbors_in_set:
                neigh_neighbors_in_set = [n_neigh for n_neigh in adj[neigh] if n_neigh in current_set]
                if len(neigh_neighbors_in_set) >= 1:
                    can_add = False
                    break

        if can_add:
            backtrack(index + 1, current_set | {s})
        backtrack(index + 1, current_set)

    # For n=3, the max_k should be easy to find.
    # For n=4, let's see.
    backtrack(0, set())
    return max_k

